contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint balBeforeC = address(c).balance;
        uint balBeforeOwner = address(this).balance;
        require(balBeforeC >= amount);

        c.withdraw(amount); if (__ESBMC_reverted()) return;

        uint balAfterC = address(c).balance;
        uint balAfterOwner = address(this).balance;

        assert(balAfterC == balBeforeC - amount && balAfterOwner == balBeforeOwner + amount);
    }
}

