// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        uint balBeforeC = address(c).balance;
        uint balBeforeOwner = address(this).balance;
        vm.assume(balBeforeC >= amount);
        try c.withdraw(amount) {} catch { return; }
        uint balAfterC = address(c).balance;
        uint balAfterOwner = address(this).balance;
        assertTrue(balAfterC == balBeforeC - amount && balAfterOwner == balBeforeOwner + amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
